from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from constance import config

class StoreTaxConfigDetailView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request, store_code):
        if not request.user.managed_stores.filter(code=store_code).exists():
            return Response({"detail": "Forbidden access to store tax configuration"}, status=403)

        tax_rate = getattr(config, f"STORE_{store_code}_TAX_RATE", None)
        tax_exempt_account = getattr(config, f"STORE_{store_code}_EXEMPT_ID", None)

        if tax_rate is None:
            return Response({"detail": "Store configuration not found"}, status=404)

        return Response({
            "store_code": store_code,
            "tax_rate": tax_rate,
            "tax_exempt_account": tax_exempt_account
        })
